// ===== SETTINGS: edit these =====
const SETTINGS = {
  subject: 'Regarding Your Application – Next Steps with Rural Root Cloud',
  signature: 'Best Regards,\nTeam Rural Root Cloud\nhttps://ruralrootcloud.com/internship/',
  meetingTitleSuffix: 'RR Cloud',     // "Jitendra <> RR Cloud"
  timeZone: 'Asia/Kolkata',
  defaultStartTime: '10:00am',        // one of the 15-minute slots, e.g. '2:30pm'
  defaultMeetLink: '',                // e.g. https://meet.google.com/abc-defg-hij
  model: 'json',                      // llm-gateway alias, see llm-gateway/providers.json
};

// Columns are matched by header name, ignoring case and extra spaces. Add your headers if they differ.
const COLUMNS = {
  name: ['name', 'full name'],
  email: ['email', 'email address', 'e-mail'],
  org: ['college / previous company', 'college', 'company'],
  program: ['program want to enroll', 'program'],
};
const MAX_OPTIONS = 300;
const DURATIONS = ['30 minutes', '45 minutes', '60 minutes'];
// Start times offered in the dropdown: every 15 minutes from 8:00am to 8:00pm
const START_TIMES = [];
for (let m = 8 * 60; m <= 20 * 60; m += 15) {
  const h = Math.floor(m / 60);
  START_TIMES.push((h % 12 || 12) + ':' + String(m % 60).padStart(2, '0') + (h < 12 ? 'am' : 'pm'));
}

const EMAIL_RE = /[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+/;
const norm = s => String(s).trim().toLowerCase().replace(/\s+/g, ' ');

function pick(row, candidates) {
  for (const c of candidates) {
    const key = Object.keys(row).find(k => norm(k) === c);
    if (key && String(row[key]).trim()) return String(row[key]).trim();
  }
  return '';
}

const filter = norm($('Start').first().json['Filter applicants (optional)'] ?? '');
const rows = $input.all().map(i => i.json).filter(r => r.row_number !== undefined);

let skippedNoEmail = 0;
const leads = [];
for (const row of rows) {
  const { row_number, ...fields } = row;
  let email = pick(fields, COLUMNS.email).match(EMAIL_RE)?.[0] ?? '';
  if (!email) {
    // No recognised email column: fall back to any cell that looks like an address
    email = Object.values(fields).map(v => String(v).match(EMAIL_RE)?.[0]).find(Boolean) ?? '';
  }
  if (!email) {
    if (Object.values(fields).some(v => String(v).trim())) skippedNoEmail++;
    continue;
  }
  const name = pick(fields, COLUMNS.name);
  const org = pick(fields, COLUMNS.org);
  const program = pick(fields, COLUMNS.program);
  const label = ['#' + row_number, name || '(no name)', org, program, email].filter(Boolean).join(' · ');
  leads.push({ rowNumber: row_number, label, name, email, org, program, fields });
}

const matching = filter
  ? leads.filter(l => Object.values(l.fields).some(v => norm(v).includes(filter)))
  : leads;
if (!matching.length) {
  throw new Error(filter
    ? 'No applicants match "' + filter + '". Run the form again with a different filter.'
    : 'No rows with an email address were found in the sheet.');
}
const shown = matching.slice(0, MAX_OPTIONS);

const notes = [shown.length + ' of ' + matching.length + ' applicants shown' + (filter ? ' (filter: "' + filter + '")' : '') + '.'];
if (matching.length > shown.length) notes.push('Use the filter on the first page to narrow the list.');
if (skippedNoEmail) notes.push(skippedNoEmail + ' row(s) without an email address were skipped.');

const formFields = [
  {
    fieldLabel: 'Applicant',
    fieldType: 'dropdown',
    fieldOptions: { values: shown.map(l => ({ option: l.label })) },
    requiredField: true,
  },
  { fieldLabel: 'Meeting date', fieldType: 'date', requiredField: true },
  {
    fieldLabel: 'Start time (' + SETTINGS.timeZone + ')',
    fieldType: 'dropdown',
    fieldOptions: { values: START_TIMES.map(option => ({ option })) },
    defaultValue: SETTINGS.defaultStartTime,
    requiredField: true,
  },
  {
    fieldLabel: 'Duration',
    fieldType: 'dropdown',
    fieldOptions: { values: DURATIONS.map(option => ({ option })) },
    defaultValue: DURATIONS[0],
    requiredField: true,
  },
  {
    fieldLabel: 'Google Meet link',
    fieldType: 'text',
    defaultValue: SETTINGS.defaultMeetLink,
    placeholder: 'https://meet.google.com/...',
    requiredField: true,
  },
  {
    fieldLabel: 'Anything specific to say? (optional)',
    fieldType: 'textarea',
    placeholder: 'e.g. resume already received; mention the DevOps batch starting in April',
  },
];

return [{ json: { formFields, description: notes.join(' '), leads: shown, settings: SETTINGS } }];

// A real email we sent, used as the style reference for the paragraphs the model writes
const EXAMPLE = `
We have reviewed your internship request. Kindly share your resume.

We understand that one of the biggest challenges IT graduates face in off-campus hiring is the requirement for experience. But for a fresher, the real question is — how do you gain experience without getting your first job?

To better understand your background, skills, and career goals, we would like to schedule a short meeting with you. This discussion will help us guide you appropriately and explain how our structured Internship Program can help you build real-world experience and industry readiness.
`.trim();

const form = $input.first().json;
const ctx = $('List leads').first().json;
const settings = ctx.settings;

const rowNumber = Number(/^#(\d+)/.exec(form['Applicant'] ?? '')?.[1]);
const lead = ctx.leads.find(l => l.rowNumber === rowNumber);
if (!lead) throw new Error('Could not find the selected applicant: ' + form['Applicant']);

// ----- Meeting line, formatted like Google Calendar: "Tuesday, March 17 · 10:00 – 10:30am"
function parseTime(s) {
  const m = String(s).trim().toLowerCase().replace(/[\s.]/g, '').match(/^(\d{1,2})(?::(\d{2}))?(am|pm)?$/);
  if (!m) return null;
  let h = Number(m[1]);
  const min = Number(m[2] ?? 0);
  if (m[3]) {
    if (h < 1 || h > 12) return null;
    h = (h % 12) + (m[3] === 'pm' ? 12 : 0);
  }
  if (h > 23 || min > 59) return null;
  return h * 60 + min;
}
const clock = mins => {
  const h = Math.floor(mins / 60) % 24;
  return { time: (h % 12 || 12) + ':' + String(mins % 60).padStart(2, '0'), ampm: h < 12 ? 'am' : 'pm' };
};

const timeKey = Object.keys(form).find(k => k.startsWith('Start time'));
const start = parseTime(form[timeKey]);
if (start === null) throw new Error('Could not read the start time "' + form[timeKey] + '". Use a format like 10:00am.');
const duration = parseInt(form['Duration'], 10) || 30;
const a = clock(start);
const b = clock(start + duration);
const timeRange = a.ampm === b.ampm
  ? a.time + ' – ' + b.time + b.ampm
  : a.time + a.ampm + ' – ' + b.time + b.ampm;

const dateValue = String(form['Meeting date'] ?? '').slice(0, 10);
const date = new Date(dateValue + 'T00:00:00Z');
if (isNaN(date)) throw new Error('Could not read the meeting date "' + form['Meeting date'] + '".');
const dateText = date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', timeZone: 'UTC' });

const meetLink = String(form['Google Meet link'] ?? '').trim();

// First name, capitalised ("jitendra kumar" -> "Jitendra")
const rawFirst = (lead.name.split(/\s+/)[0] || '').toLowerCase();
const firstName = rawFirst ? rawFirst[0].toUpperCase() + rawFirst.slice(1) : '';

const meeting = {
  title: (firstName || 'Applicant') + ' <> ' + settings.meetingTitleSuffix,
  when: dateText + ' · ' + timeRange,
  timeZone: settings.timeZone,
  link: meetLink,
};

// ----- Prompt for the paragraphs between the greeting and the meeting details
const extra = String(form['Anything specific to say? (optional)'] ?? '').trim();
const applicantDetails = Object.entries(lead.fields)
  .filter(([k, v]) => String(v).trim() && !/phone|address|timestamp/i.test(k))
  .map(([k, v]) => '- ' + k.trim() + ': ' + String(v).trim())
  .join('\n');

const system = `You write the middle part of emails from Team Rural Root Cloud, an Indian tech company, to people who applied for its internship and training programs.

The email around your text is fixed: it already starts with "Dear <name>," and "Greetings from Rural Root Cloud.", and after your text come the meeting details (date, time, Google Meet link), "Looking forward to your response." and the signature. Do not write any of those parts.

Write 3 short paragraphs in the same tone, structure and length as this example from a real email:
<example>
${EXAMPLE}
</example>

1. Say we have reviewed their request, naming the program they applied for, and ask them to share their resume.
2. One relatable challenge someone with their background faces (fresher vs. experienced, their course, their year), ending with a question like the example.
3. We would like a short meeting to understand their background, skills and career goals, and how the program they applied for can help them.

Rules:
- Formal, warm Indian business English. Plain text, no markdown, no bullet points.
- Use only the details given. Never invent facts about the applicant, the program, fees, dates, stipends or job guarantees. Never leave placeholders like [Name].
- Do not mention the meeting date, time or link.

Reply with only a JSON object: {"paragraphs": ["...", "...", "..."]}`;

const user = `Applicant (from the sheet, row ${lead.rowNumber}):
${applicantDetails}
${extra ? '\nExtra instructions from me: ' + extra : ''}`;

const requestBody = {
  model: settings.model,
  temperature: 0.5,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: user },
  ],
};

return [{ json: { lead, firstName, meeting, settings, requestBody } }];

const res = $input.first().json;
const ctx = $('Build prompt').first().json;

const content = String(res.choices?.[0]?.message?.content ?? '');
let draft;
try {
  draft = JSON.parse(content);
} catch {
  // Some free models wrap the JSON in prose or code fences
  const match = content.match(/\{[\s\S]*\}/);
  try { draft = match && JSON.parse(match[0]); } catch {}
}
let paragraphs = Array.isArray(draft?.paragraphs) ? draft.paragraphs : [draft?.body];
paragraphs = paragraphs.map(p => String(p ?? '').trim()).filter(Boolean);
if (!paragraphs.length) {
  throw new Error('The model did not return the email paragraphs: ' + content.slice(0, 500));
}

const { meeting, settings } = ctx;
const body = [
  'Dear ' + (ctx.firstName || 'Applicant') + ',',
  'Greetings from Rural Root Cloud.',
  ...paragraphs,
  [
    'Meeting Details',
    meeting.title,
    meeting.when,
    'Time zone: ' + meeting.timeZone,
    'Google Meet joining info',
    'Video call link: ' + meeting.link,
  ].join('\n'),
  'Looking forward to your response.',
  settings.signature,
].join('\n\n');

const html = s => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/\n/g, '<br>');

return [{
  json: {
    to: ctx.lead.email,
    subject: settings.subject,
    body,
    model: res.model ?? '',
    html: { to: html(ctx.lead.label), subject: html(settings.subject), body: html(body) },
  },
}];
